use std::sync::mpsc::{self, Receiver};
enum Report { Hit, Down }
fn await_heads(rx: &Receiver<Report>, heads: usize) -> u32 {
    let mut hits = 0;
    let mut down = 0;
    while down < heads {
        match rx.recv() {
            Ok(Report::Hit) => hits += 1,
            Ok(Report::Down) => down += 1,
            Err(_) => break,
        }
    }
    hits
}
fn main() {
    let (tx, rx) = mpsc::channel();
    tx.send(Report::Hit).unwrap();
    tx.send(Report::Down).unwrap();
    println!("{}", await_heads(&rx, 1));
}

use std::sync::mpsc::{self, Receiver};
use std::thread;

enum Report {
    Hit,
    Down,
}

// Count the hits, and return only once every head has reported down.
fn await_heads(rx: &Receiver<Report>, heads: usize) -> u32 {
    // this runs, but it strikes as soon as the first head falls
    let _ = heads;
    let mut hits = 0;
    for report in rx.iter() {
        match report {
            Report::Hit => hits += 1,
            Report::Down => break,
        }
    }
    hits
}

fn main() {
    // The blows each head takes: fang, venom, brine.
    let blows = [3, 2, 4];
    let (tx, rx) = mpsc::channel();
    for n in blows {
        let tx = tx.clone();
        thread::spawn(move || {
            for _ in 0..n {
                tx.send(Report::Hit).expect("receiver dropped");
            }
            tx.send(Report::Down).expect("receiver dropped");
        });
    }
    drop(tx);
    let hits = await_heads(&rx, blows.len());
    println!("{} heads down after {hits} hits", blows.len());
    println!("strike the body");
}

