    // this won't compile yet: a Ledger can't hold a whole Ledger inline
    Entry(u32, Ledger),
    Closed,
}

fn entry(amount: u32, rest: Ledger) -> Ledger {
    Ledger::Entry(amount, rest)
}

fn total(ledger: &Ledger) -> u32 {
    match ledger {
        Ledger::Entry(amount, rest) => amount + total(rest),
        Ledger::Closed => 0,
    }
}

